/** 🫧️ Live lanes wire twin, mirrors `./🦀️.rs` (generated by `wp02-gen-twins.py`). */
import type { EntityKind, EntityRef, Vec3 } from "../../../../../🎬️structural-scene/🧬️schema/🟦️.ts";

export type JsonValue = null | boolean | number | string | JsonValue[] | { [key: string]: JsonValue };

export interface FieldWrite {
  path: string;
  value: JsonValue;
}

export interface DragPreview {
  handle: string;
  writes: FieldWrite[];
  startedSeq: number;
  origin: number;
  s: number;
  entry: string;
}

export interface GhostPreview {
  writes: FieldWrite[];
  source: GhostSource;
}

export interface EvalProgress {
  running: string[];
  done: number;
  total: number;
  cancelled: boolean;
}

export interface NormTransient {
  drag: DragPreview | null;
  ghost: GhostPreview | null;
  eval: EvalProgress;
  peers: PeerDrag[];
  view: ViewLane;
}

export interface ViewLane {
  activeField: string | null;
  track: string | null;
  value: number | null;
  playing: boolean;
  clock: number;
  speed: number;
  units: string | null;
  item: number | null;
  check: number | null;
  group: number | null;
  menu: boolean;
  frame: boolean;
}

export interface PeerDrag {
  user: string;
  drag: DragPreview;
}

export interface CameraPose {
  eye: Vec3;
  target: Vec3;
  up: Vec3;
  fovY: number;
}

export interface NormPresence {
  user: string;
  selection: EntityRef[];
  hover: EntityRef | null;
  camera: CameraPose | null;
  drag: DragPreview | null;
}

export type Lane = "persistedShared" | "persistedLocal" | "ephemeralShared" | "ephemeralLocal";

export type GhostSource =
  | { kind: "remedy"; data: { checkId: string; index: number } }
  | { kind: "hover" }
  | { kind: "insert"; data: { spec: string; kind: EntityKind; at: Vec3 } };
